
function StaticShape::onDamage(%this,%type,%value,%pos,%vec,%mom,%object) { if(GameBase::getDataName(%this).description == DeathStar) { if(%type == $SniperDamageType) %value = %value * 0.6; else if(%type == $BlasterDamageType) %value = %value * 8.1; } %damageLevel = GameBase::getDamageLevel(%this); %dValue = %damageLevel + %value; %this.lastDamageObject = %object; %this.lastDamageTeam = GameBase::getTeam(%object); if(%object.isSpy && GameBase::getTeam(%this) != GameBase::getTeam(%object)) { %name = GameBase::getDataName(%this); if(%name.className == Generator || %name.className == Station) return; } if(GameBase::getTeam(%this) == GameBase::getTeam(%object)) { %name = GameBase::getDataName(%this); if(%name.className == Generator || %name.className == Station) { if(%object.isSpy) return; %TDS = $Server::TeamDamageScale; %dValue = %damageLevel + %value * %TDS; %disable = GameBase::getDisabledDamage(%this); if(!$Server::TourneyMode && %dValue > %disable - 0.05) { if(%damageLevel > %disable - 0.05) return; else %dValue = %disable - 0.05; } } } GameBase::setDamageLevel(%this,%dValue); } function StaticShape::shieldDamage(%this,%type,%value,%pos,%vec,%mom,%object) { %damageLevel = GameBase::getDamageLevel(%this); %this.lastDamageObject = %object; %this.lastDamageTeam = GameBase::getTeam(%object); if (%this.shieldStrength) { %energy = GameBase::getEnergy(%this); %strength = %this.shieldStrength; %name = GameBase::getDataName(%this); if (%type == $ShrapnelDamageType) %strength *= 0.5; else if (%type == $MortarDamageType) { if(%name.className == Station) %strength *= 0.5; else %strength *= 0.25; } else if (%type == $BlasterDamageType) %strength *= 2.0; %absorb = %energy * %strength; if (%value < %absorb) { GameBase::setEnergy(%this,%energy - (%value / %strength)); %centerPos = getBoxCenter(%this); %sphereVec = findPointOnSphere(getBoxCenter(%object),%centerPos,%vec,%this); %centerPosX = getWord(%centerPos,0); %centerPosY = getWord(%centerPos,1); %centerPosZ = getWord(%centerPos,2); %pointX = getWord(%pos,0); %pointY = getWord(%pos,1); %pointZ = getWord(%pos,2); %newVecX = %centerPosX - %pointX; %newVecY = %centerPosY - %pointY; %newVecZ = %centerPosZ - %pointZ; %norm = Vector::normalize(%newVecX @ " " @ %newVecY @ " " @ %newVecZ); %zOffset = 0; if(GameBase::getDataName(%this) == PulseSensor) %zOffset = (%pointZ-%centerPosZ) * 0.5; GameBase::activateShield(%this,%sphereVec,%zOffset); } else { GameBase::setEnergy(%this,0); StaticShape::onDamage(%this,%type,%value - %absorb,%pos,%vec,%mom,%object); } } else { StaticShape::onDamage(%this,%type,%value,%pos,%vec,%mom,%object); } } StaticShapeData DeployableForceField { shapeFile = "forcefield_5x5"; debrisId = defaultDebrisSmall; maxDamage = 4.50; visibleToSensor = true; isTranslucent = true; description = "Force Field"; }; function DeployableForceField::onDestroyed(%this) { StaticShape::onDestroyed(%this); $TeamItemCount[GameBase::getTeam(%this) @ "ForceFieldPack"]--; } StaticShapeData LargeForceField { shapeFile = "forcefield"; debrisId = defaultDebrisLarge; maxDamage = 5.00; visibleToSensor = true; isTranslucent = true; description = "Force Field"; }; function LargeForceField::onDestroyed(%this) { StaticShape::onDestroyed(%this); $TeamItemCount[GameBase::getTeam(%this) @ "LargeForceFieldPack"]--; } StaticShapeData BlastWall { shapeFile = "newdoor5"; maxDamage = 10.0; debrisId = defaultDebrisLarge; explosionId = debrisExpLarge; }; function BlastWall::onDestroyed(%this) { StaticShape::onDestroyed(%this); $TeamItemCount[GameBase::getTeam(%this) @ "TripwirePack"]--; } StaticShapeData DeployablePlatform { shapeFile = "elevator6x6thin"; debrisId = defaultDebrisSmall; maxDamage = 2.00; visibleToSensor = false; isTranslucent = true; description = "Deployable Platform"; }; function DeployablePlatform::onDestroyed(%this) { StaticShape::onDestroyed(%this); $TeamItemCount[GameBase::getTeam(%this) @ "PlatformPack"]--; } StaticShapeData DeployableTree { shapeFile = "tree1"; debrisId = defaultDebrisSmall