se::applyDamage(%object,$ExplosionDamageType,2.0,GameBase::getPosition(%object),"0 0 0","0 0 0",Player::getClient(%object)); else GameBase::applyDamage(%object,$ExplosionDamageType,0.5,GameBase::getPosition(%object),"0 0 0","0 0 0",Player::getClient(%object)); Player::applyImpulse(%object,Vector::getFromRot(GameBase::getRotation(%object), -800, 100)); playSound(debrisLargeExplosion,GameBase::getPosition(%object)); } } function CheckDestroySat(%position,%time) { if(%time > 0) { %set = newObject("set", SimSet); %num = containerBoxFillSet(%set, $StaticObjectType | $ItemObjectType, %position, 10,10,10,0); if(%num > 0) { for (%i = 0; %i < %num; %i = %i++) { %obj = GameBase::getDataName(Group::getObject(%set,%i)); if(%obj != -1 && (%obj == "DeathStarSolar" || %obj == "DeathStarRay" || %obj == "DeathStarMissile")) deleteObject(Group::getObject(%set,%i)); } schedule("CheckDestroySat(\"" @ %position @ "\", " @ %time - 1 @ ");",0.2); } else deleteObject(%set); } } StaticShapeData Hologram1 { shapeFile = "larmor"; debrisId = defaultDebrisSmall; maxDamage = 0.75; description = "Hologram"; }; function Hologram1::onDestroyed(%this) { StaticShape::onDestroyed(%this); $TeamItemCount[GameBase::getTeam(%this) @ "hologram"]--; } StaticShapeData Hologram2 { shapeFile = "marmor"; debrisId = defaultDebrisSmall; maxDamage = 1.10; description = "Hologram"; }; function Hologram2::onDestroyed(%this) { StaticShape::onDestroyed(%this); $TeamItemCount[GameBase::getTeam(%this) @ "hologram"]--; } StaticShapeData Hologram3 { shapeFile = "harmor"; debrisId = defaultDebrisSmall; maxDamage = 1.5; description = "Hologram"; }; function Hologram3::onDestroyed(%this) { StaticShape::onDestroyed(%this); $TeamItemCount[GameBase::getTeam(%this) @ "hologram"]--; } StaticShapeData DeployableTeleport { className = "DeployableTeleport"; damageSkinData = "objectDamageSkins"; shapeFile = "flagstand"; maxDamage = 1.75; maxEnergy = 200; mapFilter = 2; visibleToSensor = true; explosionId = mortarExp; debrisId = flashDebrisLarge; lightRadius = 12.0; lightType=2; lightColor = {1.0,0.2,0.2}; }; function RemoveBeam(%b) { deleteObject(%b); } function DeployableTeleport::Destruct(%this) { } function DeployableTeleport::onDestroyed(%this) { schedule("RemoveBeam("@%this.beam1@");",1); $TeamItemCount[GameBase::getTeam(%this) @ "DeployableTeleport"]--; %teleset = nameToID("MissionCleanup/Teleports"); for(%i = 0; (%o = Group::getObject(%teleset, %i)) != -1; %i++) { if(GameBase::getTeam(%o) == GameBase::getTeam(%this) && %o != %this) { GameBase::applyDamage(%o,$DebrisDamageType,20,GameBase::getPosition(%o),"0 0 0","0 0 0",%this); return; } } } function DeployableTeleport::onCollision(%this,%obj) { if(getObjectType(%obj) != "Player") return; if(Player::isDead(%obj)) return; if (Player::getClient(%obj).isSpy) { Client::sendMessage(Player::getClient(%obj), 0, "Can't teleport while undercover~waccess_denied.wav"); return; } %c = Player::getClient(%obj); %playerTeam = GameBase::getTeam(%obj); %teleTeam = GameBase::getTeam(%this); %spyTeam = GameBase::getTeam(%obj); if(%teleTeam != %playerTeam) { if((Player::getArmor(%obj) == "spyarmor") || (Player::getArmor(%obj) == "spyfemale")) { Client::SendMessage(%c,0,"Phased through enemy teleporter"); %playerTeam = GameBase::getTeam(%this); } else { Client::SendMessage(%c,0,"Wrong Team"); return; } } if(%this.disabled == true) { Client::SendMessage(%c,0,"Teleport Pad is recharging"); return; } %teleset = nameToID("MissionCleanup/Teleports"); for(%i = 0; (%o = Group::getObject(%teleset, %i)) != -1; %i++) { if(GameBase::getTeam(%o) == %playerteam && %o != %this) { if((Player::getArmor(%obj) == "darmor") || (Player::getArmor(%obj) == "harmor")) { Client::SendMessage(%c,0,"Cannot teleport in this character class"); return; } else { GameBase::playSound(%o,ForceFieldOpen,0); GameBase::playSound(%this,ForceFieldOpen,0); GameBase::SetPosition(%obj,GameBase::GetPosition(%o)); if ((Player::getArmor(%obj) == "spyarmor") || (Player::getArmor(%obj) == "spyfemale")) %playerTeam = %spyTeam; %o.Disabled = true; %this.Disabled = true; if(floor(getRandom() * 45) == 0) { Client::SendMessage(%c,0,"Teleport phased your molecular structure wrong"); GameBase::applyDamage(%obj,$CrushDamageType,0.25,GameBase::getPosition(%o),"0 0 0","0 0 0",%this); } schedule("DeployableTeleport::Reenable("@%o@");",5); schedule("DeployableTeleport::Reenable("@%this@");",5); return; } } } Client::SendMessage(%c,0,"No other pad to teleport to"); } function DeployableTeleport::Reenable(%this) { %this.disabled = false; } StaticShapeData DeployableSpring { shapeFile = "flagstand"; debrisId = defaultDebrisSmall; maxDamage = 1.50; visibleToSensor = false; isTranslucent = true; description = "Deployable Spring"; }; function DeployableSpring::onDestroyed(%this) { StaticShape::onDestroyed(%this); $TeamItemCount[GameBase::getTeam(%this) @ "SpringPack"]--; } function DeployableSpring::onCollision(%this, %obj) { if (getObjectType(%obj) == "Player") { %c = Player::getClient(%obj); %velocity = Item::getVelocity(%c); %l = 40; %m = -40; %x = getWord(%velocity,0) * 1.6; %y = getWord(%velocity,1) * 1.6; %z = 40 - (getWord(%velocity,2) * 5); if(%x > %l) %x = %l; if(%x < %m) %x = %m; if(%y > %l) %y = %l; if(%y < %m) %y = %m; if(%z <= 0) %z = 5; if(%z > 25) GameBase::playSound(%this, debrisLargeExplosion, 0); else GameBase::playSound(%this, SoundFireMortar, 0); if(Player::getArmor(%c) == "harmor") Item::setVelocity(%c, %x/1.4 @ " " @ %y/1.4 @ " " @ 15); else Item::setVelocity(%c, %x @ " " @ %y @ " " @ %z); } } 